from mk import *
from lib import fbd
STRICT["on"] = True
import math
GM = 10 * 6.4e6 ** 2; r = 6.4e6; v = math.sqrt(GM / (4 * r)); vm = 500 * v / 100; Q = 0.5 * 500 * v * v + 0.5 * 100 * vm * vm; vf = math.sqrt(2 * GM * (1 / r - 1 / (4 * r)))

def fig():
    g = Fig(560, 260, "כדור הארץ ברדיוס r, ולוויין m1 במסלול מעגלי בגובה h = 3r מעל פני כדור הארץ. בנקודה A מתנגש בו מטאוריט m2")
    g.circle(280, 200, 50, fill="var(--d-fill)", stroke="var(--d-line)"); g.line(280, 200, 315, 165, width=1.2); g.text(306, 190, "r", cls="dim", anchor="start")
    g.path("M 90,200 A 190 190 0 0 1 470,200", stroke="var(--d-dim)", width=1.4, dash="6 5")
    g.dot(280, 10); g.text(270, 14, "A", anchor="end"); g.ball(290, 10, 5); g.text(300, 14, "m₁", anchor="start")
    g.ball(430, 10, 5); g.text(440, 14, "m₂", anchor="start"); g.arrow(422, 10, 360, 10, None)
    g.dim(260, 150, 260, 10, "h", offset=0)
    return g

E(id="bagrut-1981-q2", year=1981, label="1981 שאלה 2", topic="gravitation", sub="grav-orbits", diff=4, fig=fig,
  stem=r"לוויין שמסתו $m_1 = 500\,\text{kg}$ נע במסלול מעגלי סביב כדור הארץ, בגובה $h = 3r$ מעל פני כדור הארץ. $r$ הוא רדיוס כדור הארץ, $6400\,\text{km}$. כשהלוויין נמצא מעל הנקודה $A$ שעל פני כדור הארץ, פוגע בו מטאוריט שמסתו $m_2 = 100\,\text{kg}$. בעקבות הפגיעה הלוויין והמטאוריט נעצרים לרגע, ואז מתחילים ליפול יחד אנכית כלפי מטה. על פני כדור הארץ $g = 10\,\text{m/s}^2$.",
  parts=[
    P("א", r"מה הייתה מהירות הלוויין לפני שהמטאוריט פגע בו?", num(v, "m/s"), ["principle"], [
        S(r"משוואת כוחות בכיוון המרכז", r"כוח הכבידה נותן ללוויין את התאוצה אל המרכז. המרחק מהמרכז הוא רדיוס כדור הארץ ועוד הגובה, כלומר פי ארבעה מהרדיוס. המסה של הלוויין מצטמצמת", r"\frac{GMm_1}{(4r)^2} = m_1\frac{v^2}{4r} \;\Rightarrow\; v = \sqrt{\frac{GM}{4r}}", eq=r"F = \frac{GMm}{r^2},\qquad a_R = \frac{v^2}{r}"),
        S(r"מציבים", r"מכפלת הקבוע במסת כדור הארץ שווה לתאוצת הכובד כפול ריבוע הרדיוס", r"GM = g r^2 \;\Rightarrow\; v = \sqrt{\frac{g r}{4}} = \sqrt{\frac{10 \cdot 6.4 \times 10^6}{4}} = 4 \times 10^3\,\text{m/s}", eq=r"g^* = \frac{GM}{r^2}"),
    ], r"$4 \times 10^3\,\text{m/s}$", key=r"4×10^3 m/s"),
    P("ב", r"מה הייתה מהירות המטאוריט ברגע הפגיעה?", num(vm, "m/s"), ["principle"], [
        S(r"שימור תנע", r"ההתנגשות קצרה מאוד. אחריה שניהם עומדים לרגע, ולכן התנע הכולל אפס. הכיוון החיובי הוא כיוון הלוויין", r"500 \cdot 4000 + 100\,v_m = 0", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
        S(r"פותרים", r"המהירות שלילית, כלומר נגד כיוון הלוויין", r"v_m = -2 \times 10^4\,\text{m/s}"),
    ], r"$2 \times 10^4\,\text{m/s}$, נגד הכיוון של הלוויין", key=r"2×10^4 m/s"),
    P("ג", r"כמה חום, בג'אול, נוצר בהתנגשות?", num(Q, "J"), ["principle"], [
        S(r"כל האנרגיה הקינטית", r"אחרי ההתנגשות שניהם עומדים, ולכן כל האנרגיה הקינטית של שניהם הפכה לחום", r"Q = \tfrac{1}{2} \cdot 500 \cdot (4 \times 10^3)^2 + \tfrac{1}{2} \cdot 100 \cdot (2 \times 10^4)^2 = 2.4 \times 10^{10}\,\text{J}", eq=r"E_k = \tfrac{1}{2}mv^2"),
    ], r"$2.4 \times 10^{10}\,\text{J}$", key=r"2.4×10^10 J"),
    P("ד", r"באיזו מהירות הלוויין והמטאוריט היו פוגעים בנקודה $A$, אם בזמן הנפילה לא היו פועלים עליהם כוחות חיכוך, כמו התנגדות האוויר?", num(vf, "m/s"), ["principle", "algebra"], [
        S(r"שימור אנרגיה בשדה הכבידה", r"הם מתחילים ממנוחה במרחק של ארבעה רדיוסים מהמרכז, ונופלים עד פני כדור הארץ. גובה הנפילה גדול, ולכן משתמשים באנרגיה של שדה כבידה ולא בכובד קבוע. המסה מצטמצמת", r"0 - \frac{GMm}{4r} = \tfrac{1}{2}m\,v^2 - \frac{GMm}{r} \;\Rightarrow\; v^2 = \frac{3GM}{2r}", eq=r"U = -\frac{GMm}{r}"),
        S(r"מציבים", r"מכפלת הקבוע במסה שווה לתאוצת הכובד כפול ריבוע הרדיוס", r"v = \sqrt{\frac{3 g r}{2}} = \sqrt{9.6 \times 10^7} \approx 9.8 \times 10^3\,\text{m/s}"),
    ], r"$\approx 9.8 \times 10^3\,\text{m/s}$", key=r"≈9.8×10^3 m/s"),
  ],
  concepts=["מהירות במסלול מעגלי", "התנגשות פלסטית", "אנרגיה בשדה כבידה", "מציאת GM מתאוצת הכובד"],
  summary=r"לוויין ומטאוריט שעוצרים זה את זה: המהירויות לפני הפגיעה, החום שנוצר, ומהירות הפגיעה בקרקע מאנרגיה בשדה כבידה.",
  review="הנחה שלי.\nהוספתי לנוסח את תאוצת הכובד על פני כדור הארץ. בלעדיה אי אפשר לפתור, והתשובות בדף התשובות מתאימות לה.\nמה לבדוק: רק לאשר.")
